/* Local Chirpy PWA client override, based on the 7.6.0 registration contract.
 * Readable source at the existing public URL; intentionally no automatic reload.
 */
(() => {
  'use strict';
  if (!('serviceWorker' in navigator)) return;

  const script = new URL(document.currentScript.src);
  const baseurl = script.searchParams.get('baseurl') || '';
  const workerURL = new URL(`${baseurl}/sw.min.js`, location.origin).href;
  const scopeURL = new URL(`${baseurl}/`, location.origin).href;
  const enabled = script.searchParams.get('register');

  if (!enabled) {
    // Never unregister another application sharing this origin.
    navigator.serviceWorker.getRegistration(scopeURL).then(registration => {
      if (registration && registration.scope === scopeURL &&
          registration.active?.scriptURL === workerURL) return registration.unregister();
    }).catch(() => {});
    return;
  }

  // Waiting workers ask every open in-scope page before taking control. Legacy
  // Chirpy pages cannot acknowledge: they still reload on controllerchange.
  navigator.serviceWorker.addEventListener('message', event => {
    if (event.data === 'CHIRPY_CAN_ACTIVATE' &&
        event.source?.scriptURL === workerURL && event.ports[0]) {
      event.ports[0].postMessage('CHIRPY_NO_RELOAD');
    }
  });

  navigator.serviceWorker.register(workerURL, { updateViaCache: 'none' }).then(registration => {
    const activate = () => registration.waiting?.postMessage('CHIRPY_ACTIVATE_WHEN_SAFE');
    const watch = () => {
      const worker = registration.installing;
      worker?.addEventListener('statechange', () => {
        if (worker.state === 'installed') activate();
      });
    };
    registration.addEventListener('updatefound', watch);
    watch();
    activate();

    let lastCheck = 0;
    const check = () => {
      if (document.visibilityState !== 'visible' || !navigator.onLine) return;
      activate();
      // Resume/online events may arrive together; coalesce update requests.
      if (Date.now() - lastCheck < 60000) return;
      lastCheck = Date.now();
      registration.update().catch(() => {});
    };
    window.addEventListener('pageshow', check);
    window.addEventListener('online', check);
    document.addEventListener('visibilitychange', check);
    // Active long-lived tabs discover releases without relying on a navigation.
    window.setInterval(check, 60000);
    check();
  }).catch(() => {
    // Offline/unsupported registration never prevents the page from working.
  });
})();
